SELECT DISTINCT cs.canonical_smiles, cr_sub.compound_name AS substrate_compound_name, cr_drug.compound_name AS parent_compound_name, m.met_conversion, m.pathway_key, m.organism, m.enzyme_name FROM metabolism m LEFT JOIN compound_structures cs ON cs.molregno = (SELECT molregno FROM compound_records WHERE record_id = m.substrate_record_id) LEFT JOIN compound_records cr_sub ON cr_sub.record_id = m.substrate_record_id LEFT JOIN compound_records cr_drug ON cr_drug.record_id = m.drug_record_id WHERE m.enzyme_name = 'UGT1A9' ORDER BY cs.canonical_smiles ASC, cr_sub.compound_name ASC, cr_drug.compound_name ASC, m.met_conversion ASC, m.pathway_key ASC, m.organism ASC, m.enzyme_name ASC LIMIT 200
